```rust
fn ingest_panes(&mut self, manifest: PaneManifest) {
    // 1. Flatten all panes from manifest into PaneRow vec, sorted by id
    let mut rows = Vec::new();
    for tab in tabs {
        for p in &manifest.panes[tab] {
            if is_transient_pipe_pane(p) { continue; }  // Skip zellij action pipe transients
            let id = PaneId::Terminal(p.id);
            let role = classify_pane(p.terminal_command.as_deref());  // Reads command
            let viewer_slot = if matches!(role, PaneRole::Viewer) {
                parse_viewer_slot(p.terminal_command.as_deref())
            } else {
                None
            };
            rows.push(PaneRow {
                id,
                title: p.title.clone(),
                focused: p.is_focused,
                suppressed: p.is_suppressed,
                exited: p.exited,
                floating: p.is_floating,
                role,
                viewer_slot,
                tab: *tab,
            });
        }
    }
    rows.sort_by_key(|p| p.id);
    self.panes = rows;

    // 2. Track agent labels (call sync_agent_labels)
    self.sync_agent_labels();

    // 3. Maintain slot pane (the rightmost content pane to swap into)
    // If slot was suppressed, drop it; re-adopt a visible viewer

    // 4. Track focus state (for mode-locking)
    self.sidebar_focused = sidebar_focused_this_update;
    self.focused_is_floating = focused_floating_this_update;
    self.focused_tab = focused_tab_this_update;

    // 5. Auto-lock multiplexer (Todos only)
    if self.mode == Mode::Todos {
        let want_locked = !sidebar_focused_this_update;
        if self.last_emitted_locked != Some(want_locked) {
            switch_to_input_mode(if want_locked { &InputMode::Locked } else { &InputMode::Normal });
        }
    }

    // 6. Publish content-pane count (Todos gatekeeper only, line 1072)
    self.publish_content_count();

    // 7. Ensure content-slot safety (line 1073)
    self.ensure_content_slot();

    // 8. Title every pane (line 1074)
    self.sync_pane_titles();
}
```

**Key classification logic** (panopt-zellij-logic:394-414):

```rust
pub fn classify_pane(command: Option<&str>) -> PaneRole {
    let Some(cmd) = command else { return PaneRole::Shell; };
    if cmd.contains("_viewer") {
        PaneRole::Viewer
    } else if cmd.contains("_process-run") {
        PaneRole::Process(extract_id_from_args)
    } else if cmd.contains("_agent") {
        PaneRole::Agent
    } else {
        PaneRole::Shell
    }
}
```

