1	//! The `panopt process` subcommand: a thin MCP client of the daemon's
2	//! `process_*` tools.
3	//!
4	//! Processes are the per-project instance layer of the two-layer process
5	//! model (todo #27): each row is one running (or about to run) agent,
6	//! command, or terminal. Like the rest of the CLI surface, every invocation
7	//! ensures the daemon is up, opens a one-shot `observer` MCP session, calls
8	//! one tool, prints the result, and closes.
9	
10	use std::os::unix::process::CommandExt;
11	use std::path::PathBuf;
12	use std::process::Command;
13	
14	use anyhow::{Context, Result};
15	use clap::Subcommand;
16	use serde_json::{json, Map, Value};
17	
18	use crate::daemon;
19	use crate::mcpclient::Client;
20	use crate::todo::{insert_opt, observer_url, render_scalar};
21	
22	/// What to do to the project's processes.
23	#[derive(Subcommand)]
24	pub enum ProcessCmd {
25	    /// List every process.
26	    List,
27	    /// Show one process in full.
28	    Get {
29	        /// Numeric id of the process.
30	        id: u64,
31	    },
32	    /// Add a process.
33	    Add {
34	        /// Kind of process: agent, command, or terminal.
35	        kind: String,
36	        /// Identifier-style name for the process.
37	        name: String,
38	        /// Human label shown in the cockpit (default: the name).
39	        #[arg(long = "display-name")]
40	        display_name: Option<String>,
41	        /// Shell command the process runs.
42	        #[arg(long)]
43	        command: Option<String>,
44	        /// Working directory for the launched command.
45	        #[arg(long)]
46	        cwd: Option<String>,
47	        /// Numeric id of the agent tool this process was spawned from.
48	        #[arg(long = "agent-tool-id")]
49	        agent_tool_id: Option<u64>,
50	    },
51	    /// Edit a process. Omitted options are left unchanged.
52	    Set {
53	        /// Numeric id of the process to edit.
54	        id: u64,
55	        #[arg(long)]
56	        name: Option<String>,
57	        #[arg(long = "display-name")]
58	        display_name: Option<String>,
59	        #[arg(long)]
60	        command: Option<String>,
61	        #[arg(long)]
62	        cwd: Option<String>,
63	    },
64	    /// Delete a process.
65	    Rm {
66	        /// Numeric id of the process to delete.
67	        id: u64,
68	    },
69	}
70	
71	/// Run a `panopt process` subcommand against the daemon for project `ws`.
72	pub fn run(ws: Option<PathBuf>, cmd: ProcessCmd, port: u16) -> Result<()> {
73	    daemon::ensure(None, port)?;
74	    let client = Client::connect(&observer_url(ws, port)?)?;
75	    let outcome = dispatch(&client, cmd);
76	    client.close();
77	    outcome
78	}
79	
80	fn dispatch(client: &Client, cmd: ProcessCmd) -> Result<()> {
81	    match cmd {
82	        ProcessCmd::List => {
83	            print_list(&client.call("process_list", json!({}))?);
84	        }
85	        ProcessCmd::Get { id } => {
86	            print_entry(&client.call("process_get", json!({ "process_id": id }))?);
87	        }
88	        ProcessCmd::Add {
89	            kind,
90	            name,
91	            display_name,
92	            command,
93	            cwd,
94	            agent_tool_id,
95	        } => {
96	            let mut args = Map::new();
97	            args.insert("kind".into(), json!(kind));
98	            args.insert("name".into(), json!(name));
99	            insert_opt(&mut args, "display_name", display_name);
100	            insert_opt(&mut args, "command", command);
101	            insert_opt(&mut args, "cwd", cwd);
102	            if let Some(tid) = agent_tool_id {
103	                args.insert("agent_tool_id".into(), json!(tid));
104	            }
105	            let id = client.call("process_create", Value::Object(args))?;
106	            println!("created process #{}", render_scalar(&id));
107	        }
108	        ProcessCmd::Set {
109	            id,
110	            name,
111	            display_name,
112	            command,
113	            cwd,
114	        } => {
115	            let mut args = Map::new();
116	            args.insert("process_id".into(), json!(id));
117	            insert_opt(&mut args, "name", name);
118	            insert_opt(&mut args, "display_name", display_name);
119	            insert_opt(&mut args, "command", command);
120	            insert_opt(&mut args, "cwd", cwd);
121	            client.call("process_update", Value::Object(args))?;
122	            println!("updated process #{id}");
123	        }
124	        ProcessCmd::Rm { id } => {
125	            client.call("process_delete", json!({ "process_id": id }))?;
126	            println!("deleted process #{id}");
127	        }
128	    }
129	    Ok(())
130	}
131	
132	/// `panopt _process-run` - start a process in the current pane.
133	///
134	/// Looks the process up in the daemon and `exec`s its command, so the Zellij
135	/// pane the sidebar plugin opened becomes the agent, command, or shell itself,
136	/// with no PANopt wrapper left around it. Rerunning the exited pane through
137	/// Zellij re-runs this shim, which re-fetches and re-execs.
138	pub fn exec_entry(ws: Option<PathBuf>, id: u64, port: u16) -> Result<()> {
139	    daemon::ensure(None, port)?;
140	    let client = Client::connect(&observer_url(ws.clone(), port)?)?;
141	    let entry = client.call("process_get", json!({ "process_id": id }));
142	    client.close();
143	    let entry = entry.with_context(|| format!("looking up process #{id}"))?;
144	
145	    let command = entry["command"].as_str().unwrap_or("").trim().to_string();
146	    let cwd = entry["cwd"].as_str().unwrap_or("").trim().to_string();
