/// Add `column` to `table` only if it is not already there. Used by migrations
/// that may collide with a transitional dev-database state where the column
/// landed before its `user_version` bump did. `decl` is the type+constraint
/// text after the column name, exactly as it would appear in an `ALTER TABLE`.
///
/// `column` and `table` are fixed in-crate identifiers, not caller input, so
/// interpolating them into the SQL is safe.
fn add_column_if_missing(
    conn: &Connection,
    table: &str,
    column: &str,
    decl: &str,
) -> Result<(), rusqlite::Error> {
    let mut stmt = conn.prepare(&format!("PRAGMA table_info({table})"))?;
    let mut rows = stmt.query([])?;
    while let Some(row) = rows.next()? {
        let existing: String = row.get(1)?;
        if existing == column {
            return Ok(());
        }
    }
    drop(rows);
    drop(stmt);
    conn.execute_batch(&format!("ALTER TABLE {table} ADD COLUMN {column} {decl};"))
}

/// Bring `conn` up to [`SCHEMA_VERSION`], creating tables on a fresh database.
///
/// Idempotent: a database already at the current version is left untouched.
/// Each step is gated on the stored `user_version`, so a v1 database upgrades
/// in place and a fresh one runs every step in order to the same end state.
pub(crate) fn migrate(conn: &Connection) -> Result<(), rusqlite::Error> {
    let version: i64 = conn.pragma_query_value(None, "user_version", |r| r.get(0))?;
    if version < 1 {
        conn.execute_batch(SCHEMA_V1)?;
    }
    if version < 2 {
        conn.execute_batch(SCHEMA_V2)?;
    }
    if version < 3 {
        conn.execute_batch(SCHEMA_V3)?;
    }
    if version < 4 {
        apply_v4(conn)?;
    }
    if version < 5 {
        apply_v5(conn)?;
    }
    if version < 6 {
        apply_v6(conn)?;
    }
    if version < 7 {
        apply_v7(conn)?;
    }
    if version < 8 {
        apply_v8(conn)?;
    }
    if version < 9 {
        apply_v9(conn)?;
    }
    if version < 10 {
        apply_v10(conn)?;
    }
    if version < 11 {
        apply_v11(conn)?;
    }
    if version != SCHEMA_VERSION {
        conn.pragma_update(None, "user_version", SCHEMA_VERSION)?;
    }
    Ok(())
}

/// Version 7: soft delete (todo #54).
///
/// Each item-bearing table grows a nullable `deleted_at` column. `*_delete`
/// stamps it with `datetime('now')` instead of issuing a `DELETE FROM`, and
/// every read path (`*_list`, `*_get`, `fetch_*`, the blocker-resolution helper)
/// filters on `deleted_at IS NULL`. The row stays behind so a future undelete
/// surface has something to revive; recovery / cleanup tooling is deferred.
fn apply_v7(conn: &Connection) -> Result<(), rusqlite::Error> {
    add_column_if_missing(conn, "todos", "deleted_at", "TEXT")?;
    add_column_if_missing(conn, "scratchpads", "deleted_at", "TEXT")?;
    add_column_if_missing(conn, "agent_tools", "deleted_at", "TEXT")?;
    add_column_if_missing(conn, "processes", "deleted_at", "TEXT")?;
    Ok(())
}

}

/// Version 8: tags on scratchpads (todo #61).
///
/// Scratchpads grow the same `tags` column todos got in V2, stored as a JSON
/// array string with default `'[]'`. The vocabulary is shared with todos -
/// `state::tags_list` returns the union across both kinds - so a tag chosen on
/// one surface is offered up on the other. The column uses
/// [`add_column_if_missing`] for the same dev-database drift case the earlier
/// scratchpad migration (V4) guarded against.
fn apply_v8(conn: &Connection) -> Result<(), rusqlite::Error> {
    add_column_if_missing(conn, "scratchpads", "tags", "TEXT NOT NULL DEFAULT '[]'")
}

/// Version 9: rename the `scratchpads` table to `notes` (todo #79).
///
/// "Scratchpad" implied an ephemerality the concept never had - these are
/// durable, append-oriented, shared documents that agents and humans both read
/// and write. The rename is the whole change: the columns, the unified
/// `projects.next_id` counter, and the tag vocabulary shared with todos are all
/// untouched, and every pre-existing scratchpad survives as a note with its id
/// and body intact. Whether notes should additionally carry a `type`
/// (note/plan/memory/inter-agent) is deferred to a follow-up.
///
/// Guarded like the column migrations against dev-database drift: an
/// in-development V9 binary may have renamed the table before its
/// `user_version` bump landed, so a database reporting V8 might already have a
/// `notes` table. Skip the rename in that case instead of failing on
/// "no such table: scratchpads".
fn apply_v9(conn: &Connection) -> Result<(), rusqlite::Error> {
    if table_exists(conn, "notes")? {
        return Ok(());
    }
    conn.execute_batch("ALTER TABLE scratchpads RENAME TO notes;")
}

/// Version 10: project identity distinct from the projection path (note #123,
/// todo #124).
///
/// Through V9 a project *was* its filesystem path: `projects.root` was both the
/// identity key (the unique row) and the projection location (where `.panopt/*.md`
/// is written). That conflation fragments one logical project the moment its repo
/// is cloned to another path, moved, checked out as a worktree, or mirrored on
/// another machine. V10 splits the two roles: `root` stays the projection
/// location, and a new `identity` column holds an opaque, stable repo key.
///
/// Identity is computed at the edge (the launcher / agent-config), never derived
/// inside core - so to `panopt-core` it is just an opaque string, and no git
/// dependency crosses the core boundary. The key cannot be a `UNIQUE` column on
/// an `ALTER TABLE ADD COLUMN` (SQLite forbids it), so the column is added plain,
/// back-filled from `root` to preserve today's one-project-per-path behavior for
/// every existing row, then a unique index enforces distinctness going forward.
///
/// Guarded like the other column migrations against dev-database drift: the
/// `ADD COLUMN` runs through [`add_column_if_missing`] and the index is
/// `IF NOT EXISTS`, so a database that ran an in-development V10 binary before its
/// `user_version` bump landed upgrades cleanly. The back-fill only touches rows
/// whose `identity` is still NULL, so it is safe to re-run.
fn apply_v10(conn: &Connection) -> Result<(), rusqlite::Error> {
    add_column_if_missing(conn, "projects", "identity", "TEXT")?;
    conn.execute_batch(
        "UPDATE projects SET identity = root WHERE identity IS NULL;
         CREATE UNIQUE INDEX IF NOT EXISTS idx_projects_identity ON projects(identity);",
    )
}

/// Version 11: `agent_tools.tool_type` becomes a key into the agent-type
/// profile registry rather than a free-form category (todo #139).
///
/// Through V10 the column was `TEXT NOT NULL DEFAULT 'agent'` and every row
/// carried the coarse sentinel `'agent'` (V6 set it; nothing ever changed it).
/// The agent model now treats `tool_type` as the *key* of a profile
/// ([`crate::agent_profiles`]) - `claude-code`, `codex`, ... - so the sentinel
/// has to become a real key. PANopt has only ever launched claude (the pane
/// wrapper runs `claude`), so the data is uniformly one type and the rewrite is
/// safe and data-grounded.
///
/// Two steps, conservative:
/// 1. Rewrite only the exact `'agent'` sentinel to [`DEFAULT_PROFILE_KEY`];
///    any already-specific key (a hand-set value) is left untouched.
/// 2. Rebuild the table to drop `DEFAULT 'agent'`, so a future insert must
///    supply a real key (the config form always does) instead of silently
///    re-introducing the sentinel. SQLite cannot `ALTER COLUMN`, so dropping a
///    default means the 12-step table rebuild; `agent_tools` is referenced by
///    no foreign key (`processes.agent_tool_id` is a plain INTEGER), so the
///    rebuild needs no `foreign_keys` dance and no index recreation.
///
/// Validation that a `tool_type` names a *known* profile is application-level
/// (in `state::Store`), not a SQL foreign key - the registry lives in a file,
/// not a table, so the database cannot constrain against it.
fn apply_v11(conn: &Connection) -> Result<(), rusqlite::Error> {
    // Step 1: rewrite the legacy sentinel. Bound, not interpolated, and sourced
    // from the one Rust constant that names the default profile.
    conn.execute(
        "UPDATE agent_tools SET tool_type = ?1 WHERE tool_type = 'agent'",
        [DEFAULT_PROFILE_KEY],
    )?;
    // Step 2: rebuild without the `DEFAULT 'agent'`. Column set mirrors the V6
    // create plus the V7 `deleted_at`.
    conn.execute_batch(
        "CREATE TABLE agent_tools_new (
             project_id   INTEGER NOT NULL REFERENCES projects(id),
             id           INTEGER NOT NULL,
             name         TEXT    NOT NULL,
             display_name TEXT    NOT NULL DEFAULT '',
             command      TEXT    NOT NULL DEFAULT '',
             cwd          TEXT    NOT NULL DEFAULT '',
             tool_type    TEXT    NOT NULL,
             enabled      INTEGER NOT NULL DEFAULT 1,
             position     INTEGER NOT NULL DEFAULT 0,
             created_at   TEXT    NOT NULL,
             deleted_at   TEXT,
             PRIMARY KEY (project_id, id)
         );
         INSERT INTO agent_tools_new
             (project_id, id, name, display_name, command, cwd, tool_type,
              enabled, position, created_at, deleted_at)
             SELECT project_id, id, name, display_name, command, cwd, tool_type,
                    enabled, position, created_at, deleted_at
               FROM agent_tools;
         DROP TABLE agent_tools;
         ALTER TABLE agent_tools_new RENAME TO agent_tools;",
    )
}

